def temporal(v):
 q=np.asarray(v); nz=np.sign(q[np.abs(q)>ATOL])
 return 'ZERO' if not len(nz) else 'STEADY_SIGN' if np.all(nz==nz[0]) else 'SIGN_REVERSING'
def cls(a,b,gate):
 if gate=='VIOLATED': return 'UNRESOLVED'
 if abs(a)<=ATOL and abs(b)<=ATOL:return 'ZERO'
 if a>0 and b>0:return 'ATTRACTION'
